import express from 'express';
import { readFile } from 'node:fs/promises';
import path from 'node:path';
const app = express();
const BASE = '/data/minwon/attach';
const CASE_RE = /^\d{4}-\d{6}$/;
const FILE_RE = /^[\w가-힣-]+\.(pdf|hwp|jpg|png)$/;
