  }
  try {
    const buf = await readFile(path.join(BASE, caseNo, file));
    res.type('application/octet-stream').send(buf);
  } catch {
    res.status(404).json({ error: '없음' });
  }
});
export default app;

import express, { Request, Response } from 'express';
import fs from 'fs';
import path from 'path';
import { db } from './db';
const router = express.Router();
const ROOT = path.resolve('uploads/minwon');
router.get('/attachments/:id', async (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (!Number.isInteger(id)) return res.status(400).end();
  const row = await db.attachment.findUnique({ where: { id } });
  if (!row) return res.status(404).end();
  const stream = fs.createReadStream(path.join(ROOT, row.storedName));
  res.setHeader('Content-Disposition', `inline; filename*=UTF-8''${encodeURIComponent(row.originalName)}`);
  stream.pipe(res);
});
const app = express();
app.use('/minwon', router);
app.listen(8080);

