import express from 'express';
import cors from 'cors';
const app = express();
app.use(cors());
const ALLOWED_HOSTS = new Set(['www.korea.kr', 'news-seoul.example.go.kr', 'rss.etnews.com']);
const cache = new Map();
app.get('/api/rss', async (req, res) => {
  const raw = req.query.url;
  let parsed;
  try { parsed = new URL(raw); } catch { return res.status(400).json({ error: 'url' }); }
  if (parsed.protocol !== 'https:' || !ALLOWED_HOSTS.has(parsed.hostname)) {
    return res.status(403).json({ error: '허용되지 않은 피드' });
  }
  if (cache.has(parsed.href)) return res.type('xml').send(cache.get(parsed.href));
  const r = await fetch(parsed.href);
  const xml = await r.text();
  cache.set(parsed.href, xml);
  res.type('xml').send(xml);
});
app.listen(3000);

