import express, { Request, Response } from 'express';
import fetch from 'node-fetch';
const app = express();
async function pullFeed(target: string): Promise<string> {
  const r = await fetch(target, { headers: { 'User-Agent': 'gov-rss-relay/1.0' } });
  if (!r.ok) throw new Error(`HTTP ${r.status}`);
  return r.text();
}
app.get('/relay/rss', async (req: Request, res: Response) => {
  const src = (req.query.src as string).trim();
  try {
    const xml = await pullFeed(src);
    res.type('application/rss+xml').send(xml);
  } catch (err) {
    res.status(502).json({ error: String(err) });
  }
});
app.listen(3000);

