const express = require('express');
const https = require('https');
const app = express();
const PROVIDERS = new Set(['juso', 'vworld']);
function getJson(url) {
  return new Promise((resolve, reject) => {
    https.get(url, (r) => {
      let s = '';
      r.on('data', (d) => (s += d));
      r.on('end', () => resolve(JSON.parse(s)));
    }).on('error', reject);
  });
}
app.get('/addr', async (req, res) => {
  const { provider, region, keyword } = req.query;
  if (!PROVIDERS.has(provider)) return res.status(400).send('provider');
  const data = await getJson(`https://${region}.${provider}.example.go.kr/search?q=${encodeURIComponent(keyword)}`);
  res.json(data);
});
app.listen(3000);

